import 'package:flutter/material.dart';
import '../core/theme/app_colors.dart';
class CustomButton extends StatelessWidget { final String text; final VoidCallback? onPressed; final bool loading; const CustomButton({super.key, required this.text, this.onPressed, this.loading=false}); @override Widget build(BuildContext context) => SizedBox(width:double.infinity, child: ElevatedButton(onPressed: loading ? null : onPressed, style: ElevatedButton.styleFrom(backgroundColor:AppColors.primary, foregroundColor:Colors.white, padding:const EdgeInsets.symmetric(vertical:15)), child: loading ? const SizedBox(width:20,height:20,child:CircularProgressIndicator(strokeWidth:2)) : Text(text))); }
